<script setup lang="ts">const emit=defineEmits<{submit:[value:{kind:string;format:string;from:string;to:string}]}>();const today=new Date().toISOString().slice(0,10),week=new Date(Date.now()-7*86400000).toISOString().slice(0,10),kind=ref("marketplace"),format=ref("csv"),from=ref(week),to=ref(today);</script><template><section class="admin-panel"><header><div><h2>گزارش‌های مدیریتی</h2><p>خروجی محدود، ممیزی‌شده و آماده‌سازی‌شده در پس‌زمینه</p></div></header><form class="admin-report-form" @submit.prevent="emit('submit',{kind,format,from,to})"><label>گزارش<select v-model="kind"><option value="marketplace">بازارگاه</option><option value="trust">اعتماد و ایمنی</option><option value="finance">مالی</option><option value="operations">عملیات</option></select></label><label>قالب<select v-model="format"><option value="csv">CSV</option><option value="json">JSON</option></select></label><label>از<input v-model="from" type="date" required></label><label>تا<input v-model="to" type="date" required></label><button class="button button-secondary" type="submit">ساخت گزارش</button></form></section></template>
